  2→import {
  3→  type AggregatedMessage,
  4→  isMessageManagerEvent,
  5→  type ToolCall,
  6→} from '@kynetic/shared/aggregated-message';
  7→import { Terminal } from 'lucide-svelte';
  8→import { onDestroy, onMount } from 'svelte';
  9→import { TOPIC_SESSIONS_UPDATES, wsManager } from '$lib/api/index.js';
 10→import type { HubEvent } from '$lib/api/types.js';
 11→import type { ConnectionState } from '$lib/api/websocket.js';
 12→import { createStreamingStore, type StreamingStore } from '$lib/state/index.js';
 13→
 14→interface Props {
 15→  /** Session ID to subscribe to */
 16→  sessionId: string;
 17→  /** Session status - controls cursor animation */
 18→  status: 'active' | 'paused' | 'completed' | 'failed';
 19→  /** Task title for header display */
 20→  taskTitle?: string;
 21→}
 22→
 23→const { sessionId, status, taskTitle }: Props = $props();
 24→
 25→// Terminal display settings
 26→const MAX_LINES = 100; // Store up to 100 lines
 27→const VISIBLE_LINES = 8; // Display last 8 lines
 28→
 29→// Streaming store for message aggregation
 30→let store = $state<StreamingStore | null>(null);
 31→
 32→// WebSocket state tracking for reconnection handling
 33→let previousWsState = $state<ConnectionState>('disconnected');
 34→
 35→// Scroll state
 36→let scrollContainer: HTMLDivElement | null = $state(null);
 37→let autoScroll = $state(true);
 38→
 39→// Is the session actively running?
 40→const isRunning = $derived(status === 'active');
 41→
 42→// Cleanup functions for WebSocket subscriptions
 43→const cleanupFns: (() => void)[] = [];
 44→
 45→/**
 46→ * Get tool icon based on tool name
 47→ */
 48→function getToolIcon(toolName: string): string {
 49→  const name = toolName.toLowerCase();
 50→  if (name === 'websearch' || name.includes('search')) return '🔍';
 51→  if (name === 'read') return '📄';
 52→  if (name === 'write' || name === 'edit') return '✏️';
 53→  if (name === 'glob') return '📁';
 54→  if (name === 'grep') return '🔎';
 55→  if (name === 'bash') return '$';
 56→  if (name === 'task') return '🤖';
 57→  return '🔧';
 58→}
 59→
 60→/**
 61→ * Format a tool call for display
 62→ */
 63→function formatToolCall(tool: ToolCall): string {
 64→  const icon = getToolIcon(tool.tool);
 65→  if (tool.summary) {
 66→    const truncated = tool.summary.length > 40 ? `${tool.summary.slice(0, 37)}...` : tool.summary;
 67→    return `${icon} ${tool.tool}: ${truncated}`;
 68→  }
 69→  return `${icon} ${tool.tool}...`;
 70→}
 71→
 72→/**
 73→ * Format a tool result (completed tool call)
 74→ */
 75→function formatToolResult(tool: ToolCall): string {
 76→  const statusIcon = tool.status === 'completed' ? '✓' : '✗';
 77→  return `${statusIcon} ${tool.tool} done`;
 78→}
 79→
 80→/**
 81→ * Convert aggregated messages to terminal display lines.
 82→ * This derives the compact terminal view from the store's messages.
 83→ */
 84→function messagesToLines(messages: AggregatedMessage[]): string[] {
 85→  const lines: string[] = [];
 86→
 87→  for (const msg of messages) {
 88→    switch (msg.type) {
 89→      case 'agent_message': {
 90→        // Truncate long messages for terminal view
 91→        const content = msg.content.length > 120 ? `${msg.content.slice(0, 117)}...` : msg.content;
 92→        if (content.trim()) {
 93→          lines.push(`> ${content}`);
 94→        }
 95→        break;
 96→      }
 97→
 98→      case 'user_message':
 99→        // User messages not shown in mini terminal
100→        break;
101→
102→      case 'agent_thought':
103→        lines.push('💭 thinking...');
104→        break;
105→
106→      case 'tool_call': {
107→        const tool = msg as ToolCall;
108→        // Show tool start
109→        lines.push(formatToolCall(tool));
110→        // Show tool completion if done
111→        if (tool.status === 'completed' || tool.status === 'failed') {
112→          lines.push(formatToolResult(tool));
113→        }
114→        break;
115→      }
116→    }
117→  }
118→
119→  return lines;
120→}
121→
122→// Derived: lines from streaming store messages
123→const allLines = $derived(store ? messagesToLines(store.messages) : ['> waiting for activity...']);
124→
125→// Derived: lines to display (last N lines)
126→const displayLines = $derived(allLines.slice(-VISIBLE_LINES));
127→
128→/**
129→ * Handle sessions:updates events, filtering for our session.
130→ * Only processes 'aggregated' events (semantic events from SessionMessageManager).
131→ */
132→function handleSessionsUpdate(event: HubEvent) {
133→  if (!store) return;
134→
135→  // Handle 'aggregated' events - pre-processed semantic events from SessionMessageManager
136→  if (event.event === 'aggregated' && isMessageManagerEvent(event.data)) {
137→    // Filter: only process events for our session
138→    if (event.data.sessionId !== sessionId) return;
139→
140→    // Use the streaming store's semantic event handler
141→    store.handleSemanticEvent(event.data);
142→  }
143→}
144→
145→/**
146→ * Handle WebSocket state changes to reset sequence tracking on reconnection.
147→ * Without this, the store may reject events after reconnection due to stale sequence state.
148→ */
149→function handleWsStateChange(newState: ConnectionState) {
150→  // Detect reconnection: transitioning from 'reconnecting' to 'connected'
151→  if (previousWsState === 'reconnecting' && newState === 'connected') {
152→    if (store) {
153→      store.resetSequenceTracking();
154→    }
155→  }
156→  previousWsState = newState;
157→}
158→
159→/**
160→ * Handle scroll events to detect manual scroll
161→ */
162→function handleScroll(e: Event) {
163→  const target = e.target as HTMLDivElement;
164→  // If user scrolls up, disable auto-scroll
165→  // Re-enable if they scroll back to bottom
166→  const isAtBottom = target.scrollHeight - target.scrollTop - target.clientHeight < 10;
167→  autoScroll = isAtBottom;
168→}
169→
170→// Effect to auto-scroll when lines change
171→$effect(() => {
172→  // Access displayLines to create dependency
173→  displayLines;
174→
175→  if (autoScroll && scrollContainer) {
176→    requestAnimationFrame(() => {
177→      if (scrollContainer) {
178→        scrollContainer.scrollTop = scrollContainer.scrollHeight;
179→      }
180→    });
181→  }
182→});
183→
184→onMount(() => {
185→  // Create streaming store for this session
186→  store = createStreamingStore(sessionId);
187→
188→  // Listen for WebSocket state changes to handle reconnection
189→  const unsubWsState = wsManager.onStateChange(handleWsStateChange);
190→  cleanupFns.push(unsubWsState);
191→
192→  // Subscribe to the global sessions:updates topic
193→  wsManager.subscribe([TOPIC_SESSIONS_UPDATES]);
194→
195→  // Handle events and filter for our session
196→  const unsub = wsManager.onTopic(TOPIC_SESSIONS_UPDATES, handleSessionsUpdate);
197→  cleanupFns.push(unsub);
198→
199→  // Cleanup subscription on unmount
200→  cleanupFns.push(() => {
201→    wsManager.unsubscribe([TOPIC_SESSIONS_UPDATES]);
202→  });
203→});
204→
205→onDestroy(() => {
206→  for (const cleanup of cleanupFns) {
207→    cleanup();
208→  }
209→});
210→</script>
211→
212→<div class="h-28 overflow-hidden rounded-lg border border-orange-900/50 bg-zinc-950">
213→	<!-- Header bar -->
214→	<div class="flex items-center justify-between border-b border-zinc-800 bg-zinc-900/80 px-3 py-1.5">
215→		<div class="flex items-center gap-2">
216→			<Terminal class="h-3.5 w-3.5 text-orange-500" />
217→			<span class="text-xs text-zinc-400">Live Output</span>
218→		</div>
219→		{#if isRunning}
220→			<span class="h-2 w-2 animate-pulse rounded-full bg-orange-500" title="Running"></span>
221→		{:else}
222→			<span class="h-2 w-2 rounded-full bg-zinc-600" title="Stopped"></span>
223→		{/if}
224→	</div>
225→
226→	<!-- Task info line (optional) -->
227→	{#if taskTitle}
228→		<div class="truncate border-b border-zinc-800/50 px-3 py-1 text-xs text-zinc-500">
229→			{taskTitle}
230→		</div>
231→	{/if}
232→
233→	<!-- Terminal content -->
234→	<div
235→		bind:this={scrollContainer}
236→		onscroll={handleScroll}
237→		class="h-[calc(100%-2.5rem)] overflow-y-auto px-3 py-2 font-mono text-xs text-emerald-400/80"
238→	>
239→		{#each displayLines as line, i}
240→			<div class="leading-relaxed opacity-80 transition-opacity hover:opacity-100">
241→				{line}
242→				{#if i === displayLines.length - 1 && isRunning}
243→					<span class="animate-pulse">▌</span>
244→				{/if}
245→			</div>
246→		{/each}
247→	</div>
248→</div>
