    65→  if (tool.summary) {
    66→    const truncated = tool.summary.length > 40 ? `${tool.summary.slice(0, 37)}...` : tool.summary;
    67→    return `${icon} ${tool.tool}: ${truncated}`;
    68→  }
    69→  return `${icon} ${tool.tool}...`;
    70→}
    71→
    72→/**
    73→ * Format a tool result (completed tool call)
    74→ */
    75→function formatToolResult(tool: ToolCall): string {
    76→  const statusIcon = tool.status === 'completed' ? '✓' : '✗';
    77→  return `${statusIcon} ${tool.tool} done`;
    78→}
    79→
    80→/**
    81→ * Convert aggregated messages to terminal display lines.
    82→ * This derives the compact terminal view from the store's messages.
    83→ */
    84→function messagesToLines(messages: AggregatedMessage[]): string[] {
    85→  const lines: string[] = [];
    86→
    87→  for (const msg of messages) {
    88→    switch (msg.type) {
    89→      case 'agent_message': {
    90→        // Truncate long messages for terminal view
    91→        const content = msg.content.length > 120 ? `${msg.content.slice(0, 117)}...` : msg.content;
    92→        if (content.trim()) {
    93→          lines.push(`> ${content}`);
    94→        }
    95→        break;
    96→      }
    97→
    98→      case 'user_message':
    99→        // User messages not shown in mini terminal
   100→        break;
   101→
   102→      case 'agent_thought':
   103→        lines.push('💭 thinking...');
   104→        break;
   105→
   106→      case 'tool_call': {
   107→        const tool = msg as ToolCall;
   108→        // Show tool start
   109→        lines.push(formatToolCall(tool));
   110→        // Show tool completion if done
   111→        if (tool.status === 'completed' || tool.status === 'failed') {
   112→          lines.push(formatToolResult(tool));
   113→        }
   114→        break;
   115→      }
   116→    }
   117→  }
   118→
   119→  return lines;
   120→}
   121→
   122→// Derived: lines from streaming store messages
   123→const allLines = $derived(store ? messagesToLines(store.messages) : ['> waiting for activity...']);
   124→
   125→// Derived: lines to display (last N lines)
   126→const displayLines = $derived(allLines.slice(-VISIBLE_LINES));
   127→
   128→/**
   129→ * Handle sessions:updates events, filtering for our session.
   130→ * Only processes 'aggregated' events (semantic events from SessionMessageManager).
   131→ */
   132→function handleSessionsUpdate(event: HubEvent) {
   133→  if (!store) return;
   134→
   135→  // Handle 'aggregated' events - pre-processed semantic events from SessionMessageManager
   136→  if (event.event === 'aggregated' && isMessageManagerEvent(event.data)) {
   137→    // Filter: only process events for our session
   138→    if (event.data.sessionId !== sessionId) return;
