   147→ * Without this, the store may reject events after reconnection due to stale sequence state.
   148→ */
   149→function handleWsStateChange(newState: ConnectionState) {
   150→  // Detect reconnection: transitioning from 'reconnecting' to 'connected'
   151→  if (previousWsState === 'reconnecting' && newState === 'connected') {
   152→    if (store) {
   153→      store.resetSequenceTracking();
   154→    }
   155→  }
   156→  previousWsState = newState;
   157→}
   158→
   159→/**
   160→ * Handle scroll events to detect manual scroll
   161→ */
   162→function handleScroll(e: Event) {
   163→  const target = e.target as HTMLDivElement;
   164→  // If user scrolls up, disable auto-scroll
   165→  // Re-enable if they scroll back to bottom
   166→  const isAtBottom = target.scrollHeight - target.scrollTop - target.clientHeight < 10;
   167→  autoScroll = isAtBottom;
   168→}
   169→
   170→// Effect to auto-scroll when lines change
   171→$effect(() => {
   172→  // Access displayLines to create dependency
   173→  displayLines;
   174→
   175→  if (autoScroll && scrollContainer) {
   176→    requestAnimationFrame(() => {
   177→      if (scrollContainer) {
   178→        scrollContainer.scrollTop = scrollContainer.scrollHeight;
   179→      }
   180→    });
   181→  }
   182→});
   183→
   184→onMount(() => {
   185→  // Create streaming store for this session
   186→  store = createStreamingStore(sessionId);
   187→
   188→  // Listen for WebSocket state changes to handle reconnection
   189→  const unsubWsState = wsManager.onStateChange(handleWsStateChange);
   190→  cleanupFns.push(unsubWsState);
   191→
   192→  // Subscribe to the global sessions:updates topic
   193→  wsManager.subscribe([TOPIC_SESSIONS_UPDATES]);
   194→
   195→  // Handle events and filter for our session
   196→  const unsub = wsManager.onTopic(TOPIC_SESSIONS_UPDATES, handleSessionsUpdate);
   197→  cleanupFns.push(unsub);
   198→
   199→  // Cleanup subscription on unmount
   200→  cleanupFns.push(() => {
   201→    wsManager.unsubscribe([TOPIC_SESSIONS_UPDATES]);
   202→  });
   203→});
   204→
   205→onDestroy(() => {
   206→  for (const cleanup of cleanupFns) {
   207→    cleanup();
   208→  }
   209→});
   210→</script>
   211→
   212→<div class="h-28 overflow-hidden rounded-lg border border-orange-900/50 bg-zinc-950">
   213→	<!-- Header bar -->
