   215→		<div class="flex items-center gap-2">
   216→			<Terminal class="h-3.5 w-3.5 text-orange-500" />
   217→			<span class="text-xs text-zinc-400">Live Output</span>
   218→		</div>
   219→		{#if isRunning}
   220→			<span class="h-2 w-2 animate-pulse rounded-full bg-orange-500" title="Running"></span>
   221→		{:else}
   222→			<span class="h-2 w-2 rounded-full bg-zinc-600" title="Stopped"></span>
   223→		{/if}
   224→	</div>
   225→
   226→	<!-- Task info line (optional) -->
   227→	{#if taskTitle}
   228→		<div class="truncate border-b border-zinc-800/50 px-3 py-1 text-xs text-zinc-500">
   229→			{taskTitle}
   230→		</div>
   231→	{/if}
   232→
   233→	<!-- Terminal content -->
   234→	<div
   235→		bind:this={scrollContainer}
   236→		onscroll={handleScroll}
   237→		class="h-[calc(100%-2.5rem)] overflow-y-auto px-3 py-2 font-mono text-xs text-emerald-400/80"
   238→	>
   239→		{#each displayLines as line, i}
