/**
 * Streaming Message Store
 *
 * Aggregates streaming session events into coherent UI messages.
 * Uses Svelte 5 runes for reactivity.
 *
 * @see specs/STREAMING_MESSAGE_AGGREGATION.md
 * @see kynetic-r0i5 - Phase 1: Core aggregation types and streaming store
 */

import {
  type AgentMessage,
  type AgentThought,
  type AggregatedMessage,
  type AggregationState,
  type Command,
  createAggregationState,
  createSessionMeta,
  generateMessageId,
  type MessageManagerEvent,
  type PlanEntry,
  parseMessageId,
  roleForMessageType,
  type SessionMeta,
  type ToolCall,
  type UserMessage,
} from '@kynetic/shared/aggregated-message';
import {
  type SessionMessageEventData,
  type SessionMetaEventData,
  type SessionStatusEventData,
  type SessionThoughtEventData,
  type SessionToolCallUpdateEventData,
  type SessionToolResultEventData,
  type SessionToolUseEventData,
  translateAcpToUiEvent,
  type UiEventType,
} from '@kynetic/shared/ui-event-translator';
import type { HubEvent } from '$lib/api/index.js';

// =============================================================================
// Role Determination
// =============================================================================

/**
 * Get the role for a UI event type.
 *
 * Per spec Section 4.2:
 * - User events: 'user_message'
 * - Agent events: all others except 'meta'
 * - Meta events: return null (don't participate in turn tracking)
 */
export function roleForUiEvent(eventType: UiEventType): 'user' | 'agent' | null {
  switch (eventType) {
    case 'user_message':
      return 'user';
    case 'agent_message':
    case 'agent_thought':
    case 'tool_use':
    case 'tool_call_update':
    case 'tool_result':
    case 'status':
      return 'agent';
    case 'meta':
      return null; // Meta events don't participate in turn tracking
    default:
      return null;
  }
}

// =============================================================================
// Turn Tracking
// =============================================================================

/**
 * Update turn/block indices based on role change.
 *
 * Per spec Section 4.3:
 * - Role change = new turn (turnIndex++, blockIndex reset to 0)
 * - Same role, new block = blockIndex++
 * - Same role, same type = no change (appending)
 */
function updateTurnTracking(
  state: AggregationState,
  role: 'user' | 'agent',
  isNewBlock: boolean,
): void {
  if (role !== state.lastRole) {
    // Role change = new turn
    state.turnIndex++;
    state.blockIndex = 0;
    state.lastRole = role;
  } else if (isNewBlock) {
    // Same role, new block type
    state.blockIndex++;
  }
  // Same role, same type = no change (appending)
}

// =============================================================================
// Helper Functions
// =============================================================================

/**
 * Finalize the active streaming message.
 */
function finalizeActiveMessage(state: AggregationState, timestamp?: string): void {
  if (state.activeMessageId) {
    const activeMsg = state.messages.find((m) => m.id === state.activeMessageId);
    if (activeMsg) {
      activeMsg.is_streaming = false;
      if (timestamp) {
        activeMsg.updated_at = timestamp;
      }
    }
    state.activeMessageId = null;
  }
}

/**
 * Find a message by ID.
 *
 * IMPORTANT: Must search the messages array (not messageById Map) to get the
 * reactive proxy. The Map stores the original plain object, which bypasses
 * Svelte 5's $state reactivity when mutated.
 * @see kynetic-w9e2
 */
function findMessageById(state: AggregationState, id: string): AggregatedMessage | undefined {
  // Search the reactive array to get the proxy, not the plain object from Map
  return state.messages.find((m) => m.id === id);
}

// =============================================================================
// Event Handlers
// =============================================================================

/**
 * Handle text events (user_message, agent_message).
 *
 * Per spec Section 4.6:
 * - If same type and still streaming, append content
 * - Otherwise, finalize active and start new message
 *
 * IMPORTANT: We always look up through state.messages to ensure Svelte 5
 * reactivity works. Direct object references bypass the $state proxy.
 */
function handleTextEvent(
  messageType: 'user_message' | 'agent_message',
  content: string,
  timestamp: string,

  timestamp: string,
  state: AggregationState,
): void {
  const role = roleForUiEvent(messageType);
  if (!role) throw new Error(`No role for message type: ${messageType}`);

  // Empty string signals new message boundary (Claude streaming API convention)
  // Finalize current message if exists, then return - next content chunk creates new message
  if (content === '') {
    if (state.activeMessageId) {
      finalizeActiveMessage(state, timestamp);
    }
    // Don't create a new empty message - wait for actual content
    return;
  }

  // Check continuation: same type, still streaming
  // Look up through messages array to get proxied reference for Svelte 5 reactivity
  if (state.activeMessageId) {
    const activeMsg = state.messages.find((m) => m.id === state.activeMessageId);
    if (activeMsg?.type === messageType && activeMsg.is_streaming) {
      // Append in place - mutation goes through Svelte proxy
      const msg = activeMsg as AgentMessage | UserMessage;
      msg.content += content;
      msg.updated_at = timestamp;
      return;
    }
  }

  // Start new message
  finalizeActiveMessage(state, timestamp);

  const isNewBlock = state.lastRole === role; // Same role = new block
  updateTurnTracking(state, role, isNewBlock);

  const newMessage: AgentMessage | UserMessage = {
    id: generateMessageId(state),
    type: messageType,
    content: content,
    started_at: timestamp,
    updated_at: timestamp,
    is_streaming: true,
  };

  state.messages.push(newMessage);
  state.messageById.set(newMessage.id, newMessage);
  state.activeMessageId = newMessage.id;
}

