 * IMPORTANT: We always look up through state.messages to ensure Svelte 5
 * reactivity works. Direct object references bypass the $state proxy.
 */
function handleThoughtEvent(
  data: SessionThoughtEventData,
  timestamp: string,
  state: AggregationState,
): void {
  const content = data.content || '';
  const role = roleForUiEvent('agent_thought'); // Always "agent"
  if (!role) throw new Error('No role for agent_thought');

  // Check continuation - look up through messages array for Svelte 5 reactivity
  if (state.activeMessageId) {
    const activeMsg = state.messages.find((m) => m.id === state.activeMessageId);
    if (activeMsg?.type === 'agent_thought' && activeMsg.is_streaming) {
      // Append in place - mutation goes through Svelte proxy
      const msg = activeMsg as AgentThought;
      msg.content += content;
      msg.updated_at = timestamp;
      return;
    }
  }

  // Start new thought block
  finalizeActiveMessage(state, timestamp);

  const isNewBlock = state.lastRole === role;
  updateTurnTracking(state, role, isNewBlock);

  const thought: AgentThought = {
    id: generateMessageId(state),
    type: 'agent_thought',
    content: content,
    started_at: timestamp,
    updated_at: timestamp,
    is_streaming: true,
  };

