/**
 * Handle tool_use events.
 *
 * Per spec Section 4.8:
 * - Tool calls are tracked in pendingTools, NOT as activeMessage
 * - If tool_call_id already exists, update the existing tool (streaming input)
 * - Otherwise, create new tool call with status "pending"
 */
function handleToolUse(
  data: SessionToolUseEventData,
  timestamp: string,
  state: AggregationState,
): void {
  const role = roleForUiEvent('tool_use'); // Always "agent"
  if (!role) throw new Error('No role for tool_use');

  // Check if this is an update to existing tool call (streaming input)
  const existingId = state.pendingTools.get(data.tool_call_id);
  if (existingId !== undefined) {
    const existing = findMessageById(state, existingId) as ToolCall | undefined;
    if (existing) {
      // Tool input arrives as progressively more complete JSON objects
      // Replace with newer (more complete) version
      if (data.input != null) existing.input = data.input;
      if (data.tool) existing.tool = data.tool;
      if (data.summary) existing.summary = data.summary;
      existing.updated_at = timestamp;
    }
    return;
  }

  // New tool call
  finalizeActiveMessage(state, timestamp);

  const isNewBlock = state.lastRole === role;
  updateTurnTracking(state, role, isNewBlock);

  const toolMessage: ToolCall = {
    id: generateMessageId(state),
    type: 'tool_call',
    tool_call_id: data.tool_call_id,
    tool: data.tool,
    summary: data.summary,
    input: data.input,
    status: 'pending',
    started_at: timestamp,
    updated_at: timestamp,
    is_streaming: true,
  };

  state.messages.push(toolMessage);
  state.messageById.set(toolMessage.id, toolMessage);
  // Store message.id instead of index (resilient to array reordering)
  state.pendingTools.set(data.tool_call_id, toolMessage.id);
  // Note: tool calls don't become activeMessage (text can follow immediately)
}

/**
 * Handle tool_call_update events.
 *
 * Per spec Section 4.9:
 * - Handle non-terminal status updates (pending -> running)
 * - Does NOT finalize activeMessage or clear pendingTools
 */
function handleToolCallUpdate(
  data: SessionToolCallUpdateEventData,
  timestamp: string,
  state: AggregationState,
): void {
  const messageId = state.pendingTools.get(data.tool_call_id);

  if (messageId === undefined) {
    // Tool not found - may have been created before we connected
    console.warn(`[Aggregation] tool_call_update for unknown tool_call_id=${data.tool_call_id}`);
    return;
  }

  const tool = findMessageById(state, messageId) as ToolCall | undefined;
  if (!tool) return;

  // Update status: pending -> running
  if (data.status === 'in_progress') {
    tool.status = 'running';
  }

  // Optional: capture partial output if provided
  if (data.partial_output !== undefined) {
    tool.output = data.partial_output;
  }

  tool.updated_at = timestamp;

  // IMPORTANT: Do NOT finalize activeMessage or clear pendingTools
  // This is a progress update, not a turn boundary
}

